// AI: below section was generated by an AI
// Host-side test of the received beat's clock (ar_net_beat.h).
//   g++ -std=c++17 -Wall -Wextra -fsanitize=address,undefined -I../../../wled00 net_beat_host_test.cpp -o net_beat_host_test && ./net_beat_host_test
#include "ar_net_beat.h"
#include <cstdio>
#include <random>

static int failures = 0;
#define CHECK(c, ...) do { if (!(c)) { failures++; printf("FAIL line %d: ", __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

// The sender: a steady beat, quantised as it is on the wire.
static ArNetBeatPacket sent(double beats, float bpm, bool bar = true, bool phrase = true) {
  const int64_t n = (int64_t)floor(beats);
  ArNetBeatPacket p = {};
  p.bpm = floorf(bpm * 100 + 0.5f) / 100.0f;
  p.phase = floor((beats - n) * 256.0) / 256.0f;
  p.beatCount = (uint16_t)n;
  p.beatInBar = bar ? n % 4 + 1 : 0;
  p.beatInPhrase = phrase ? n % 32 + 1 : 0;
  p.phraseBeats = phrase ? 32 : 0;
  p.downbeatKnown = true;
  return p;
}

struct Result { double worst, lag, wobble; int doubled, wrongBar, wrongPhrase; };

// 60 s of packets every 25 ms, delayed 2 ms plus up to jitterMs, a share of them lost; read every 5 ms.
// With bunchMs the packets are held, as an access point holds multicast, and released together.
// With stalls, now and then everything is held for 450 ms: more than half a beat.
static Result run(float bpm, double jitterMs, double loss, uint32_t t0, bool pll, double bunchMs = 0, bool stalls = false) {
  std::mt19937 rng(7);
  std::uniform_real_distribution<double> u(0, 1);
  ArNetBeatClock c;
  Result r = {};
  double sum = 0, sumSq = 0; int n = 0; int64_t lastBeat = -1; uint32_t lastElapsed = 0;
  struct Arr { uint32_t at; ArNetBeatPacket p; };
  Arr pend[4000]; int np = 0;
  uint32_t prev = 0;
  for (uint32_t t = 0; t < 60000; t += 25) {
    if (u(rng) < loss) continue;
    uint32_t at = t + 2 + (uint32_t)(u(rng) * jitterMs);
    if (bunchMs > 0) at = (uint32_t)((floor(t / bunchMs) + 1) * bunchMs) + 1 + (uint32_t)(u(rng) * 3);
    if (stalls && t % 4000 < 450) at = t - t % 4000 + 451 + (uint32_t)(u(rng) * 3);
    if (at < prev) at = prev;             // one stream stays in order
    prev = at;
    pend[np++] = {at, sent(t * (double)bpm / 60000.0, bpm)};
  }
  int k = 0; ArNetBeatPacket lastP = {}; uint32_t lastAt = 0;
  for (uint32_t t = 0; t < 60000; t += 5) {
    while (k < np && pend[k].at <= t) { c.packet(pend[k].p, t0 + pend[k].at, t0 + t); lastP = pend[k].p; lastAt = pend[k].at; k++; }
    if (t < 2000) continue;
    ArNetBeatNow o;
    if (!c.now(t0 + t, o)) { CHECK(false, "no beat at %u", t); continue; }
    const double truth = t * (double)bpm / 60000.0;
    const int64_t tb = (int64_t)floor(truth);
    double err;
    if (pll) err = (o.beatInPhrase - 1 + o.progress) - ((tb % 32) + (truth - tb));
    else     err = (lastP.phase + (t - lastAt) * (double)bpm / 60000.0) - (truth - tb);   // each packet sets the phase
    const double m = pll ? 32 : 1;
    err -= m * floor(err / m + 0.5);
    const double ms = err * 60000.0 / bpm;
    if (fabs(ms) > r.worst) r.worst = fabs(ms);
    sum += ms; sumSq += ms * ms; n++;
    if (lastBeat >= 0) {
      const int32_t step = (int32_t)(o.beatsElapsed - lastElapsed);
      if (step < 0 && step > -60000) r.doubled++;
    }
    lastBeat = 1; lastElapsed = o.beatsElapsed;
    if (fabs(truth - floor(truth) - 0.5) < 0.2) {       // mid-beat, where the labels are unambiguous
      if (o.beatInBar != tb % 4 + 1) r.wrongBar++;
      if (o.beatInPhrase != tb % 32 + 1) r.wrongPhrase++;
    }
  }
  // The lag is the mean delay, which the loop cannot see; the wobble about it is what it is there to reduce.
  r.lag = sum / n;
  r.wobble = sqrt(sumSq / n - r.lag * r.lag);
  return r;
}

int main() {
  for (double j : {0.0, 10.0, 40.0, 100.0}) {
    for (float bpm : {90.0f, 128.0f, 174.0f}) {
      const Result a = run(bpm, j, 0.05, 1000, true), b = run(bpm, j, 0.05, 1000, false);
      printf("jitter %5.0f ms  %5.0f BPM  PLL lag %6.1f wobble %5.1f worst %5.1f ms | unsmoothed lag %6.1f wobble %5.1f worst %5.1f ms | doubled %d bar %d phrase %d\n",
             j, bpm, a.lag, a.wobble, a.worst, b.lag, b.wobble, b.worst, a.doubled, a.wrongBar, a.wrongPhrase);
      CHECK(a.doubled == 0, "a beat was shown twice");
      CHECK(a.wrongBar == 0 && a.wrongPhrase == 0, "wrong labels");
      if (j >= 10) CHECK(a.wobble < b.wobble, "the PLL does not steady the beat");
    }
  }

  for (float bpm : {90.0f, 128.0f, 174.0f}) {
    const Result a = run(bpm, 0, 0.05, 1000, true, 102.4), b = run(bpm, 0, 0.05, 1000, false, 102.4);
    printf("bunches 102 ms   %5.0f BPM  PLL lag %6.1f wobble %5.1f worst %5.1f ms | unsmoothed lag %6.1f wobble %5.1f worst %5.1f ms | doubled %d bar %d phrase %d\n",
           bpm, a.lag, a.wobble, a.worst, b.lag, b.wobble, b.worst, a.doubled, a.wrongBar, a.wrongPhrase);
    CHECK(fabs(a.lag) < 15 && a.wobble < b.wobble, "bunched delivery");
    CHECK(a.doubled == 0 && a.wrongBar == 0 && a.wrongPhrase == 0, "bunched labels");
  }
  for (float bpm : {90.0f, 128.0f, 174.0f}) {
    const Result a = run(bpm, 0, 0.05, 1000, true, 102.4, true), b = run(bpm, 0, 0.05, 1000, true, 307.2);
    printf("450 ms stalls    %5.0f BPM  lag %6.1f wobble %5.1f worst %5.1f | 307 ms bunches: lag %6.1f wobble %5.1f worst %5.1f ms | doubled %d/%d bar %d/%d phrase %d/%d\n",
           bpm, a.lag, a.wobble, a.worst, b.lag, b.wobble, b.worst, a.doubled, b.doubled, a.wrongBar, b.wrongBar, a.wrongPhrase, b.wrongPhrase);
    CHECK(a.worst < 60 && b.worst < 60, "held packets moved the beat");
    CHECK(a.doubled + a.wrongBar + a.wrongPhrase + b.doubled + b.wrongBar + b.wrongPhrase == 0, "held packets moved the labels");
  }
  { // the sender's phase moves back 0.3 of a beat, at 120 BPM, where the window is one beat long
    ArNetBeatClock c; ArNetBeatNow o; uint32_t t = 0;
    for (; t < 5000; t += 25) c.packet(sent(t * 120.0 / 60000.0, 120.0f), t, t);
    for (const uint32_t end = t + 2000; t < end; t += 25) c.packet(sent(t * 120.0 / 60000.0 - 0.3, 120.0f), t, t);
    c.now(t, o); double e = o.progress - (t * 120.0 / 60000.0 - 0.3); e -= floor(e + 0.5);
    CHECK(fabs(e) < 0.12, "back step: %.3f beats off", e);
  }
  { // two receivers that join at different times agree on bar and phrase
    ArNetBeatClock a, b; ArNetBeatNow x, y;
    for (uint32_t t = 0; t < 20000; t += 25) {
      const ArNetBeatPacket p = sent(t * 128.0 / 60000.0, 128.0f);
      a.packet(p, t, t); if (t >= 7300) b.packet(p, t, t);
    }
    CHECK(a.now(20003, x) && b.now(20003, y) && x.beatInBar == y.beatInBar && x.beatInPhrase == y.beatInPhrase, "late joiner differs");
  }
  { // the bar's place unknown: still 1..4, counting
    ArNetBeatClock c; ArNetBeatNow o; int seen = 0;
    for (uint32_t t = 0; t < 8000; t += 25) {
      c.packet(sent(t * 120.0 / 60000.0, 120.0f, false, false), t, t);
      CHECK(c.now(t, o) && o.beatInBar >= 1 && o.beatInBar <= 4 && o.beatInPhrase == 0, "bar %u", o.beatInBar);
      seen |= 1 << o.beatInBar;
    }
    CHECK(seen == 0x1E, "bar did not count: %x", seen);
  }
  { // one glitched label is ignored, a lasting one is taken and moves the generation
    ArNetBeatClock c; ArNetBeatNow o; uint32_t t = 0;
    for (; t < 4000; t += 25) c.packet(sent(t * 120.0 / 60000.0, 120.0f), t, t);
    c.now(t, o); const uint32_t g = o.gen; const uint8_t bar = o.beatInBar;
    ArNetBeatPacket p = sent(t * 120.0 / 60000.0, 120.0f);
    p.beatInBar = p.beatInBar % 4 + 1; c.packet(p, t, t); c.now(t, o);
    CHECK(o.gen == g && o.beatInBar == bar, "a single glitch moved the bar");
    for (int i = 0; i < 50; i++) { t += 25; p = sent(t * 120.0 / 60000.0 + 1, 120.0f); c.packet(p, t, t); }
    c.now(t, o);
    CHECK(o.gen != g, "a lasting change was not taken");
  }
  { // it ends four beats after the last packet, and a restart moves the generation
    ArNetBeatClock c; ArNetBeatNow o;
    c.packet(sent(0.25, 120.0f), 100, 100); c.now(100, o); const uint32_t g = o.gen;
    CHECK(c.now(100 + 1990, o), "ended early"); CHECK(!c.now(100 + 2010, o), "did not end");
    c.packet(sent(40.5, 120.0f), 30000, 30000); CHECK(c.now(30000, o) && o.gen != g, "restart kept the generation");
  }
  { // nonsense tempos, the tempo jump, and the count and clock wrapping
    ArNetBeatClock c; ArNetBeatNow o;
    ArNetBeatPacket p = sent(0, 120.0f); p.bpm = 0; c.packet(p, 5, 5); CHECK(!c.now(5, o), "0 BPM");
#ifndef __FAST_MATH__   // which says there is no NaN; a packet cannot carry one
    p.bpm = NAN; c.packet(p, 5, 5); CHECK(!c.now(5, o), "NaN BPM");
#endif
    // 0.9 of a beat is 0.1 before one already shown: the clock waits at the beat for it, then is on it.
    c.packet(sent(0.0, 120.0f), 10, 10); c.packet(sent(0.9, 140.0f), 20, 20);
    CHECK(c.now(20, o) && fabsf(o.bpm - 140) < 0.01f && o.progress < 0.05f, "tempo jump: %f %f", o.bpm, o.progress);
    uint32_t t = 20;
    while (t < 2000) { t += 25; c.packet(sent(0.9 + (t - 20) * 140.0 / 60000.0, 140.0f), t, t); }
    const double want = 0.9 + (t - 20) * 140.0 / 60000.0;
    double e = 0; if (c.now(t, o)) e = o.progress - want; e -= floor(e + 0.5);
    CHECK(fabs(e) < 0.02, "tempo jump did not settle: %f", e);
    CHECK(o.beatInBar == (int64_t)floor(want) % 4 + 1, "tempo jump: bar %u", o.beatInBar);
    const Result w = run(128.0f, 10.0, 0.0, 0xFFFFFFFFu - 30000u, true);
    CHECK(w.doubled == 0 && w.wrongBar == 0 && w.wrongPhrase == 0 && w.worst < 60, "millis() wrap");
  }
  printf(failures ? "%d FAILURES\n" : "all passed\n", failures);
  return failures ? 1 : 0;
}
